<script setup lang="ts">
/* Federal CSV of the season's licences, generated by the server in the strict format of the MyFFME import
   (tests/exports/test_ffme_golden_master.py): the page only shows the counts and saves the file. */
import { inject, onMounted, ref } from "vue";
import UiBadge from "../../../components/ui/UiBadge.vue";
import UiButton from "../../../components/ui/UiButton.vue";
import UiCard from "../../../components/ui/UiCard.vue";
import UiTile from "../../../components/ui/UiTile.vue";
import { CLIENT_KEY, errorText, type Schemas } from "../../../lib/client";
import { createFfmeApi } from "../../../services/ffme";
import { saveExport } from "../../../lib/download";

const emit = defineEmits<{ toast: [message: string, ms?: number] }>();
const ffmeApi = createFfmeApi(inject(CLIENT_KEY)!);

const stats = ref<Schemas["FfmeStats"] | null>(null);
const includeFinished = ref(true);
const busy = ref(false);

async function load(): Promise<void> {
  stats.value = null;
  try {
    stats.value = await ffmeApi.stats();
  } catch (e) {
    emit("toast", `❌ Impossible de charger les statistiques FFME : ${errorText(e)}`, 8000);
  }
}

async function download(): Promise<void> {
  busy.value = true;
  try {
    const name = await saveExport(ffmeApi.exportFile(includeFinished.value), "import_ffme.csv");
    emit("toast", `✅ Fichier FFME « ${name} » téléchargé !`);
  } catch (e) {
    emit("toast", `❌ Échec de génération du CSV FFME : ${errorText(e)}`, 8000);
  } finally {
    busy.value = false;
  }
}

onMounted(load);
defineExpose({ reload: load });

const count = (n: number | undefined) => (n === undefined ? "…" : String(n));
</script>

<template>
  <UiCard>
    <div class="mb-3 flex flex-wrap items-start justify-between gap-3">
      <div class="min-w-0 flex-1 basis-80">
        <h2 class="mb-1 flex flex-wrap items-center gap-2 text-base font-bold">
          🇫🇷 Export Intranet Fédéral FFME (CSV Officiel)
          <UiBadge color="blue" variant="soft">Format Fédéral</UiBadge>
        </h2>
        <p class="text-[13px] text-slate-500">
          Génère le fichier CSV normalisé prêt à être importé dans l'intranet fédéral FFME (séparateur point-virgule, codification
          automatique des assurances, options ski/vtt/trail et numéros de licence existants).
        </p>
      </div>
      <a
        href="https://myffme.fr/federal/gestion-des-licences/saisir-les-licences-via-csv/2027"
        target="_blank"
        rel="noopener"
        class="rounded-lg bg-slate-200 px-2.5 py-1.5 text-xs font-bold text-slate-700 hover:bg-slate-300"
      >
        🌐 Ouvrir MyFFME (Import CSV)
      </a>
    </div>

    <div class="mb-4 grid grid-cols-2 gap-2.5 md:grid-cols-4">
      <UiTile label="Total éligibles">
        <span data-testid="ffme-total" class="text-lg">{{ count(stats?.estimated_total) }}</span>
      </UiTile>
      <UiTile label="Renouvellements">
        <span data-testid="ffme-renewals" class="text-lg text-green-600">{{ count(stats?.renewals_count) }}</span>
      </UiTile>
      <UiTile label="Nouvelles licences">
        <span data-testid="ffme-new" class="text-lg text-blue-600">{{ count(stats?.new_licences_count) }}</span>
      </UiTile>
      <UiTile label="Lignes ignorées">
        <span data-testid="ffme-ignored" class="text-lg text-club-orange">{{ count(stats?.ignored_count) }}</span>
      </UiTile>
    </div>

    <div class="mb-4 rounded-lg border border-slate-200 bg-slate-50 p-3">
      <div class="mb-2 text-[12.5px] font-semibold">OPTIONS D'EXPORTATION</div>
      <label class="flex cursor-pointer items-start gap-2 text-[13px]">
        <input v-model="includeFinished" type="checkbox" data-testid="ffme-include-finished" class="mt-1" />
        <span>
          <b>Inclure les adhérents dont le statut est « Terminé »</b>
          (permet d'exporter l'intégralité des adhérents validés de la saison)
        </span>
      </label>
      <p class="mt-1 ml-6 text-[11.5px] text-slate-500">
        Décochez cette option si vous souhaitez exporter uniquement les nouveaux inscrits non encore traités.
      </p>
    </div>

    <div
      v-if="stats?.ignored_details.length"
      data-testid="ffme-ignored-details"
      class="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2.5 text-xs text-amber-800"
    >
      <b>⚠️ Adhérents ignorés (données incomplètes) :</b>
      <ul class="mt-1 list-disc pl-5">
        <li v-for="(item, i) in stats.ignored_details" :key="i">{{ item }}</li>
      </ul>
    </div>

    <div
      v-if="stats?.to_check_details.length"
      data-testid="ffme-to-check-details"
      class="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2.5 text-xs text-amber-800"
    >
      <b>🔎 À corriger dans la fiche adhérent (exportés avec un champ vide) :</b>
      <ul class="mt-1 list-disc pl-5">
        <li v-for="(item, i) in stats.to_check_details" :key="i">{{ item }}</li>
      </ul>
    </div>

    <UiButton data-testid="ffme-download" :busy="busy && 'Génération du CSV FFME…'" @click="download">
      📥 Télécharger le fichier CSV FFME
    </UiButton>
  </UiCard>
</template>
